(function(window, document){
  'use strict';

  function escapeHtml(str){
    return str.replace(/[&<>"']/g,function(ch){return ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;','\'':'&#39;'}[ch]);});
  }

  function simpleMarkdownToHtml(md){
    if(!md) return '';
    var text = escapeHtml(md);
    text = text.replace(/^### (.*)$/gm,'<h3>$1</h3>');
    text = text.replace(/^## (.*)$/gm,'<h2>$1</h2>');
    text = text.replace(/^# (.*)$/gm,'<h1>$1</h1>');
    text = text.replace(/^> (.*)$/gm,'<blockquote>$1</blockquote>');
    text = text.replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');
    text = text.replace(/\*([^*]+)\*/g,'<em>$1</em>');
    text = text.replace(/`([^`]+)`/g,'<code>$1</code>');
    text = text.replace(/\n\n/g,'</p><p>');
    return '<p>' + text + '</p>';
  }

  function createButton(label, title, onClick){
    var btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'toastui-editor-toolbar-button';
    btn.title = title;
    var icon = document.createElement('span');
    icon.className = 'toastui-editor-toolbar-icons';
    icon.textContent = label;
    btn.appendChild(icon);
    btn.addEventListener('click', onClick);
    return btn;
  }

  function Editor(options){
    options = options || {};
    if(!options.el){throw new Error('Editor requires an element.');}
    var el = options.el;
    var height = options.height || '480px';
    var initialValue = options.initialValue || '';

    var root = document.createElement('div');
    root.className = 'toastui-editor-defaultUI';
    root.style.height = height;

    var toolbar = document.createElement('div');
    toolbar.className = 'toastui-editor-toolbar';

    var container = document.createElement('div');
    container.className = 'toastui-editor-main';

    var split = document.createElement('div');
    split.className = 'toastui-editor-md-split';

    var mdWrap = document.createElement('div');
    mdWrap.className = 'toastui-editor-md-container';

    var textarea = document.createElement('textarea');
    textarea.className = 'toastui-editor-contents';
    textarea.value = initialValue;

    mdWrap.appendChild(textarea);

    var preview = document.createElement('div');
    preview.className = 'toastui-editor-md-preview';

    split.appendChild(mdWrap);
    split.appendChild(preview);
    container.appendChild(split);

    var statusbar = document.createElement('div');
    statusbar.className = 'toastui-editor-statusbar';
    statusbar.textContent = 'Markdown';

    root.appendChild(toolbar);
    root.appendChild(container);
    root.appendChild(statusbar);

    var updatePreview = function(){
      preview.innerHTML = simpleMarkdownToHtml(textarea.value);
    };

    var insertWrap = function(before, after){
      var start = textarea.selectionStart || 0;
      var end = textarea.selectionEnd || 0;
      var value = textarea.value;
      var selected = value.substring(start, end) || '';
      var replacement = before + selected + after;
      textarea.setRangeText(replacement, start, end, 'end');
      textarea.dispatchEvent(new Event('input'));
      textarea.focus();
    };

    var buttons = [
      createButton('B','Bold',function(){insertWrap('**','**');}),
      createButton('I','Italic',function(){insertWrap('*','*');}),
      createButton('#','Heading',function(){insertWrap('# ','');}),
      createButton('`','Code',function(){insertWrap('`','`');}),
      createButton('-','List',function(){insertWrap('- ','');}),
      createButton('>','Quote',function(){insertWrap('> ','');})
    ];

    buttons.forEach(function(btn){toolbar.appendChild(btn);});

    textarea.addEventListener('input', updatePreview);
    updatePreview();

    el.innerHTML = '';
    el.appendChild(root);

    this.focus = function(){textarea.focus();};
    this.getMarkdown = function(){return textarea.value;};
    this.setMarkdown = function(v){textarea.value=v||'';updatePreview();};
  }

  if(!window.toastui){window.toastui = {};} 
  window.toastui.Editor = Editor;
})(window, document);
